MATCH (p:PlantItem {tag: 'P-3601B'})-[:measured_by]->(i:PlantItem)
RETURN DISTINCT i.tag AS tag
ORDER BY tag;

MATCH (item:PlantItem {tag: 'H-1501'})-[:is_drawn_on]->(sheet:Sheet)
RETURN DISTINCT sheet.sheet_id AS sheet_id
ORDER BY sheet_id;

MATCH (a:PlantItem {tag: 'E-1403'}), (b:PlantItem {tag: 'EH-1401'}), (excluded:PlantItem {tag: 'E-1404'})
RETURN a.tag AS from_tag, b.tag AS to_tag,
       EXISTS {
         MATCH (a) ((n:PlantItem)-[:line_to]->(m:PlantItem) WHERE n <> excluded AND m <> excluded)+ (b)
       } AS reachable

MATCH (loop:ProcessControlFunction {loop_tag: 'FIC-44047'})-[:send_signal_to*1..]->(actuator:PlantItem {kind: 'actuator'})-[:control]->(valve:Valve)
RETURN DISTINCT valve.tag AS tag
ORDER BY tag;

MATCH (item:PlantItem {tag: 'F-2001B'})-[:is_drawn_on]->(sheet:Sheet)
