ORDER BY sheet_id;

MATCH (f:ProcessInstrumentationFunction {loop_tag: 'LSHH-26006'})-[:send_signal_to*1..]->(a:ActuatingFunction)-[:control]->(v:Valve)
RETURN DISTINCT v.tag AS tag
ORDER BY tag;

MATCH (v:PlantItem {tag: 'V-3701'})-[:is_drawn_on]->(s:Sheet)
RETURN v.tag AS tag, s.sheet_id AS sheet_id
ORDER BY sheet_id;

MATCH (a:PlantItem {tag: 'K-5401'}), (b:PlantItem {tag: 'V-5402'}), (v:PlantItem:Valve)
WHERE v <> a AND v <> b
  AND EXISTS { (a)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(b) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag;

MATCH (v:PlantItem {tag: 'V-4701'})-[:measured_by]->(i:PlantItem)
