MATCH (tank:PlantItem {tag: 'TK-1202'})-[:line_to]-(v:Valve)<-[:control]-(a:ActuatingFunction)<-[:send_signal_to*1..]-(c:ProcessControlFunction)
RETURN DISTINCT c.loop_tag AS tag
ORDER BY tag;

MATCH (e:PlantItem {tag: 'E-3803'}), (t:PlantItem {tag: 'T-3801'}), (v:Valve)
WHERE EXISTS { (e)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(t) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag

MATCH (a:PlantItem {tag: 'E-5104'}), (b:PlantItem {tag: 'EH-5101'})
RETURN a.tag AS from_tag, b.tag AS to_tag,
       EXISTS { (a)-[:line_to*1..]->(b) } AS reachable;

MATCH (equipment:Equipment)-[:measured_by]->(instrument:ProcessInstrumentationFunction {loop_tag: 'TI-46032'})
