MATCH (t:PlantItem {tag: 'T-1801'})-[:line_to]-(v:Valve)<-[:control]-(a:ActuatingFunction)<-[:send_signal_to*1..]-(loop:ProcessControlFunction)
RETURN DISTINCT loop.loop_tag AS tag
ORDER BY tag;

MATCH (a:PlantItem {tag: 'M-4101'}), (b:PlantItem {tag: 'V-4201'})
RETURN EXISTS {
  MATCH p = shortestPath((a)-[:line_to*]->(b))
  WHERE NONE(n IN nodes(p) WHERE n.tag = 'XV-42016')
} AS reachable_without_XV_42016, a.tag AS source_tag, b.tag AS destination_tag, 'XV-42016' AS avoided_tag

MATCH (m:PlantItem {tag: 'M-1301'})-[:line_to]-(v:Valve)<-[:control]-(a:PlantItem {kind: 'actuator'})<-[:send_signal_to*1..]-(c:ProcessControlFunction)
