MATCH (c:ProcessControlFunction {loop_tag: 'FIC-23011'})-[:send_signal_to*1..]->(a:PlantItem {kind: 'actuator'})-[:control]->(v:Valve)
RETURN DISTINCT v.tag AS tag
ORDER BY tag;

MATCH (v:PlantItem:AngleBallValve {unit_id: '49'})
RETURN v.tag AS tag
ORDER BY tag;

MATCH (a:PlantItem {tag: 'TK-3903'}), (b:PlantItem {tag: 'F-4001A'})
WHERE EXISTS {
  MATCH (a) ((x)-[:line_to]->(y) WHERE x.tag <> 'P-3901A')+ (b)
}
RETURN b.tag AS tag

MATCH (a:PlantItem {tag: 'T-2401'}), (b:PlantItem {tag: 'E-2402'}), (v:Valve)
WHERE EXISTS { (a)-[:line_to*1..]->(v) }
