} AND NOT EXISTS {
  (a)-[:line_to*1..]->(:PlantItem {tag: 'E-5201'})-[:line_to*0..]->(b)
} AS reachable_without_E5201, a.tag AS from_tag, b.tag AS to_tag, 'E-5201' AS excluded_tag

MATCH (a:PlantItem {tag: 'H-2901'}), (b:PlantItem {tag: 'E-2901'})
