       EXISTS {
         MATCH (a) ((x:PlantItem)-[:line_to]->(y:PlantItem)
                    WHERE x.tag <> 'R-2901' AND y.tag <> 'R-2901')+ (b)
       } AS can_flow_without_R2901

MATCH (a:PlantItem {tag: 'P-1901B'}), (b:PlantItem {tag: 'V-2201'})
