MATCH (:PlantItem {tag: 'XV-12014'})-[:line_to]->(item:PlantItem)
RETURN DISTINCT item.tag AS tag
ORDER BY tag;

MATCH (e:Equipment)-[:measured_by]->(s:PlantItem {loop_tag: 'PIC-17022', kind: 'instrument'})
RETURN DISTINCT e.tag AS tag
ORDER BY tag;

MATCH (a:PlantItem {tag: 'EJ-3401'}), (b:PlantItem {tag: 'XV-35009'})
MATCH p = shortestPath((a)-[:line_to*]->(b))
RETURN [n IN nodes(p) WHERE n.kind IN ['equipment', 'valve'] | n.tag] AS tags;

MATCH (v:PlantItem:AngleBallValve {unit_id: '49'})
RETURN v.tag AS tag
ORDER BY tag;

MATCH (v:SwingCheckValve:PlantItem {unit_id: '18'})
RETURN v.tag AS tag
ORDER BY tag;

MATCH (:PlantItem {tag: 'E-3802'})-[:is_drawn_on]->(s:Sheet)
RETURN DISTINCT s.sheet_id AS sheet_id
ORDER BY sheet_id;

MATCH (p:PlantItem {tag: 'P-4902A'})
MATCH (d:PlantItem:Equipment)
WHERE EXISTS { (p)-[:line_to*1..]->(d) }
MATCH (v:PlantItem:Valve)
WHERE EXISTS { (p)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(d) }
  AND NOT EXISTS {
    MATCH (p)-[:line_to*1..]->(u:PlantItem:Valve)
    WHERE u <> v
      AND EXISTS { (u)-[:line_to*1..]->(v) }
  }
RETURN DISTINCT v.tag AS tag
